CREATE TABLE workout_session (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES weekly_assignment(id), template_id TEXT NOT NULL REFERENCES workout_template(id), name TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('active','paused','completed','abandoned')), started_at INTEGER NOT NULL, ended_at INTEGER, version INTEGER NOT NULL DEFAULT 0, resume_exercise_id TEXT, resume_set_id TEXT, CHECK(ended_at IS NULL OR ended_at>=started_at), CHECK((status IN ('completed','abandoned'))=(ended_at IS NOT NULL)));
CREATE UNIQUE INDEX one_unfinished_workout ON workout_session((1)) WHERE status IN ('active','paused');
CREATE INDEX workout_assignment ON workout_session(assignment_id);
CREATE TABLE exercise_session (id TEXT PRIMARY KEY, workout_id TEXT NOT NULL REFERENCES workout_session(id), exercise_id TEXT NOT NULL REFERENCES exercise(id), name TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), status TEXT NOT NULL CHECK(status IN ('pending','active','paused','completed','skipped')), started_at INTEGER, ended_at INTEGER, removed_at INTEGER, CHECK(ended_at IS NULL OR started_at IS NULL OR ended_at>=started_at), UNIQUE(id,workout_id));
CREATE INDEX exercises_workout ON exercise_session(workout_id);
CREATE UNIQUE INDEX one_active_exercise ON exercise_session(workout_id) WHERE status='active';
CREATE TABLE set_session (id TEXT PRIMARY KEY, workout_id TEXT NOT NULL REFERENCES workout_session(id), exercise_session_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), type TEXT NOT NULL CHECK(type IN ('normal','warmup','dropset','failure')), target_reps INTEGER NOT NULL CHECK(target_reps BETWEEN 0 AND 1000), target_grams INTEGER NOT NULL CHECK(target_grams BETWEEN 0 AND 2000000), rest_ms INTEGER NOT NULL CHECK(rest_ms BETWEEN 0 AND 3600000), status TEXT NOT NULL CHECK(status IN ('pending','active','paused','completed','skipped')), actual_reps INTEGER CHECK(actual_reps BETWEEN 0 AND 1000), actual_grams INTEGER CHECK(actual_grams BETWEEN 0 AND 2000000), started_at INTEGER, ended_at INTEGER, notes TEXT NOT NULL DEFAULT '', removed_at INTEGER, FOREIGN KEY(exercise_session_id,workout_id) REFERENCES exercise_session(id,workout_id), CHECK(ended_at IS NULL OR started_at IS NULL OR ended_at>=started_at), CHECK(status!='completed' OR (actual_reps IS NOT NULL AND actual_grams IS NOT NULL AND started_at IS NOT NULL AND ended_at IS NOT NULL)), UNIQUE(id,workout_id));
CREATE INDEX sets_exercise ON set_session(exercise_session_id);
CREATE UNIQUE INDEX one_running_set ON set_session(workout_id) WHERE status IN ('active','paused');
CREATE TABLE workout_pause (id TEXT PRIMARY KEY, workout_id TEXT NOT NULL REFERENCES workout_session(id), started_at INTEGER NOT NULL, ended_at INTEGER, CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE UNIQUE INDEX one_open_pause ON workout_pause(workout_id) WHERE ended_at IS NULL;
CREATE TABLE rest_period (id TEXT PRIMARY KEY, workout_id TEXT NOT NULL REFERENCES workout_session(id), set_id TEXT NOT NULL, planned_ms INTEGER NOT NULL CHECK(planned_ms>=0), started_at INTEGER NOT NULL, ended_at INTEGER, reason TEXT, FOREIGN KEY(set_id,workout_id) REFERENCES set_session(id,workout_id), CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE UNIQUE INDEX one_open_rest ON rest_period(workout_id) WHERE ended_at IS NULL;
CREATE TRIGGER rest_requires_no_running_set BEFORE INSERT ON rest_period WHEN NEW.ended_at IS NULL AND EXISTS(SELECT 1 FROM set_session WHERE workout_id=NEW.workout_id AND status IN ('active','paused')) BEGIN SELECT RAISE(ABORT,'Cannot rest during an active set'); END;
CREATE TRIGGER set_requires_no_rest BEFORE UPDATE OF status ON set_session WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM rest_period WHERE workout_id=NEW.workout_id AND ended_at IS NULL) BEGIN SELECT RAISE(ABORT,'End rest before starting a set'); END;
